  /**
   * The crop growth stage models this model uses, to limit its risk to the stages a disease affects or to set its biofix.
   */
  crop_models: string[]
  /**
   * The model's results, the main one first.
   */
  outputs: QuantityInfo[]
  /**
   * Choices that change the model's results, such as a resistance class or a biofix date. Each is a parameter of the run endpoints.
   */
  options: OptionInfo[]
  /**
   * The date the model starts counting from, and its default. Null when the model has no biofix.
   */
  biofix: BiofixInfo | null
  /**
   * The crop stages the disease affects. The model's risk is shown only between them. Null when risk is shown all season.
   */
  susceptible: SusceptibilityInfo | null
  /**
   * What a planting date adds to the model. Null when the model takes no planting date.
   */
  crop: CropInfo | null
  /**
   * How the model's results become risk levels. Null when the model gives no risk, such as a crop growth stage model.
   */
  risk: RiskInfo | null
  /**
   * The model's inputs as numbers you can set yourself with `POST /models/{model_id}/evaluate`, with their usual ranges. Their values are in the units shown here; the request takes them in its own units.
   */
  explorer: ExplorerInputInfo[]
  /**
   * What `POST /models/{model_id}/evaluate` returns beyond `outputs`, such as a daily rate.
   */
